package com.autoops.workflow.entity;import jakarta.persistence.*;@Entity @Table(name="wait_until_steps")public class WaitUntilStep extends WorkflowStep{@Column(name="check_type",nullable=false)private String checkType;@Column(name="check_command",columnDefinition="text")private String checkCommand;@Column(name="expected_output")private String expectedOutput;@Column(name="check_interval_seconds",nullable=false)private Integer checkIntervalSeconds=5;@Column(name="timeout_seconds",nullable=false)private Integer timeoutSeconds=120;}
